import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Task Coverage and Definition of Done","description":"Hearth's eight task coverage categories, A0–A3 autonomy levels, and completion evidence for different task types.","frontmatter":{"title":"Task Coverage and Definition of Done","description":"Hearth's eight task coverage categories, A0–A3 autonomy levels, and completion evidence for different task types.","outline":[2,3]},"headers":[],"relativePath":"en/product/task-coverage.md","filePath":"en/product/task-coverage.md","lastUpdated":null}`),i={name:"en/product/task-coverage.md"};function d(n,t,s,c,l,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<p class="eyebrow">TASK COVERAGE &amp; DONE</p><h1 id="task-coverage-and-definition-of-done" tabindex="-1">Task Coverage and Definition of Done <a class="header-anchor" href="#task-coverage-and-definition-of-done" aria-label="Permalink to &quot;Task Coverage and Definition of Done&quot;">​</a></h1><p class="lead">Hearth does not aim to “do everything”; instead, it uses eight explicit Task categories, autonomy levels, and verifiers to define what is worth doing, when it can be done automatically, and what counts as done.</p><h2 id="coverage-of-eight-task-categories" tabindex="-1">Coverage of Eight Task Categories <a class="header-anchor" href="#coverage-of-eight-task-categories" aria-label="Permalink to &quot;Coverage of Eight Task Categories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task family</th><th>Typical work</th><th>Preferred execution method</th></tr></thead><tbody><tr><td>Communication and collaboration</td><td>Email, IM, meeting notes, follow-ups, calendar coordination</td><td>Connector + Native/Codex + approval</td></tr><tr><td>Documents and content</td><td>docx, xlsx, pptx, PDF, Markdown, reports, translation, rewriting</td><td>Document/Data Engine, Native, Codex</td></tr><tr><td>Research and information organization</td><td>Search, reading, comparison, citations, summaries, knowledge base</td><td>Native + Browser + Codex</td></tr><tr><td>Code and R&amp;D</td><td>Repository changes, tests, Issue, PR, code review</td><td>Codex + test/CI tools</td></tr><tr><td>Data and spreadsheets</td><td>Cleaning, reconciliation, statistics, charts, import/export</td><td>Document/Data Engine + Python sidecar</td></tr><tr><td>Web and SaaS</td><td>Login, forms, downloads, uploads, back-office operations</td><td>Browser Executor</td></tr><tr><td>Desktop applications</td><td>Software without APIs, system settings, cross-application workflows</td><td>GUI Executor</td></tr><tr><td>Personal affairs</td><td>Forms, appointments, bills, reminders, device operations</td><td>Connector, Browser, GUI, high-risk approval</td></tr></tbody></table><p>A Task can be handled collaboratively by multiple executors; “research competitors and write it into the weekly report” may use Browser, Native, Document Engine, and Codex at the same time.</p><h2 id="autonomy-levels" tabindex="-1">Autonomy Levels <a class="header-anchor" href="#autonomy-levels" aria-label="Permalink to &quot;Autonomy Levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Behavior</th><th>Default use</th></tr></thead><tbody><tr><td>A0 Suggest</td><td>Only generate suggestions, drafts, or plans</td><td>New scenarios, high risk, unvalidated capabilities</td></tr><tr><td>A1 Controlled execution</td><td>Automatically complete low-risk steps; require approval for medium risk on first occurrence</td><td>Default for Stage 1–2</td></tr><tr><td>A2 Authorized execution</td><td>Automatically complete authorized actions within a Mandate; high-risk actions still require approval</td><td>After Stage 4</td></tr><tr><td>A3 Supervised autonomy</td><td>Run over long periods while retaining approval, budget, kill switch, and Receipt</td><td>Long-term goals</td></tr></tbody></table><p>Autonomy must be configured independently by Task family, source, time period, device, risk, and amount; a single “fully automatic switch” cannot cover all scenarios.</p><h2 id="definition-of-done" tabindex="-1">Definition of “Done” <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of “Done”&quot;">​</a></h2><p>Natural-language “done” is not evidence of completion. Different Tasks require different verifiers:</p><table tabindex="0"><thead><tr><th>Task</th><th>Evidence of completion</th></tr></thead><tbody><tr><td>Code/Issue/PR</td><td>Tests, type checks, diff, CI, or human review</td></tr><tr><td>Documents</td><td>Structure checks, citation checks, formatting checks, user acceptance</td></tr><tr><td>Email draft</td><td>Recipient, fact, and tone checks; approval before sending</td></tr><tr><td>Email sending</td><td>Approval, Broker execution record, provider message id, or an explicit uncertain state</td></tr><tr><td>Web operations</td><td>DOM/accessibility state, screenshots, final state, and Receipt</td></tr><tr><td>Desktop operations</td><td>Accessibility tree, screenshots, target state, and human confirmation</td></tr><tr><td>Research</td><td>Traceable sources; key claims have citations</td></tr><tr><td>Calendar</td><td>Time, time zone, participants, conflict checks, and calendar Receipt</td></tr><tr><td>Data</td><td>schema, row count, sampling, reconciliation, and reproducible scripts</td></tr></tbody></table>',12)])])}const f=e(i,[["render",d]]);export{u as __pageData,f as default};
